def is_balanced(text: str) -> bool:
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    opening = {'(', '[', '{'}

    for char in text:
        if char in opening:
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack.pop() != bracket_map[char]:
                return False

    return not stack
